-- Minimal contracts for isolated program-transaction regression tests; never deployed.
\ir shooting-bootstrap.sql
insert into auth.users values('00000000-0000-0000-0000-000000000001');
alter table teams alter column id set default gen_random_uuid();
alter table players alter column id set default gen_random_uuid();
create function public.create_team_with_owner(p_name text) returns jsonb language plpgsql as $$ declare tid uuid; begin insert into teams(name) values(p_name) returning id into tid; insert into team_roles values(tid,auth.uid()); return jsonb_build_object('team_id',tid); end $$;
create function public.create_managed_player(p_first_name text,p_birth_year integer) returns jsonb language plpgsql as $$ declare pid uuid; begin insert into players(owner_user_id,first_name) values(auth.uid(),p_first_name) returning id into pid; insert into player_guardians values(pid,auth.uid()); return jsonb_build_object('player_id',pid); end $$;
create function public.add_my_player_to_team(p_team_id uuid,p_player_id uuid) returns jsonb language plpgsql as $$ begin insert into team_memberships(team_id,player_id,status) values(p_team_id,p_player_id,'active'); return '{"success":true}'::jsonb; end $$;
create table team_week_plans(id uuid primary key,team_id uuid references teams(id),name text,start_date date,tier text,use_tier_scaling boolean,status text,created_by_user_id uuid references auth.users(id),updated_at timestamptz default now());
create table team_week_plan_days(id uuid primary key default gen_random_uuid(),team_week_plan_id uuid references team_week_plans(id) on delete cascade,date date,title text,notes text,unique(team_week_plan_id,date));
create table team_week_plan_tasks(id uuid primary key default gen_random_uuid(),team_week_plan_day_id uuid references team_week_plan_days(id) on delete cascade,sort_order integer,task_type text check(task_type in ('shooting','conditioning','mobility','recovery','prep','other')),label text,target_type text,target_value integer,shot_type text,shots_expected integer,is_required boolean,video_url text);
create table practice_cards(id uuid primary key default gen_random_uuid(),team_id uuid references teams(id),date date,mode text,tier text,title text,notes text,locked boolean default false,created_by_user_id uuid references auth.users(id),published_at timestamptz,program_source text default 'team',updated_at timestamptz default now());
create unique index practice_cards_team_schedule_unique on practice_cards(team_id,date,mode) where program_source='team';
create table practice_tasks(id uuid primary key default gen_random_uuid(),practice_card_id uuid references practice_cards(id) on delete cascade,sort_order integer,task_type text check(task_type in ('shooting','conditioning','mobility','recovery','prep','other','video')),label text,target_type text,target_value integer,shot_type text,shots_expected integer,is_required boolean,video_url text,program_source text default 'team');
create table task_completions(id uuid primary key default gen_random_uuid(),practice_task_id uuid references practice_tasks(id) on delete cascade,player_id uuid references players(id),completed boolean,completed_at timestamptz,shots_logged integer);
create table session_completions(id uuid primary key default gen_random_uuid(),practice_card_id uuid references practice_cards(id) on delete cascade,status text);
